// C uses ULONG_MAX for the two uninitialized minimum-price fields. NetHack's
// legal prices are safe JavaScript integers, so MAX_SAFE_INTEGER preserves
// the sentinel's ordering while keeping later shop arithmetic numeric and
// serializable.
const UNSEEN_OBJECT_PRICE = Number.MAX_SAFE_INTEGER;

// Each alias reads and writes `this[source]`, so every entry can share one
// descriptor. A fresh getter and setter per entry would give each entry its
// own V8 hidden class, and every read or copy of an entry would take a slow
// path.
const OBJCLASS_ALIAS_DESCRIPTORS = Object.fromEntries(Object.entries({
    oc_bimanual: 'oc_big',
    oc_bulky: 'oc_big',
    oc_skill: 'oc_subtyp',
    oc_armcat: 'oc_subtyp',
    oc_hitbon: 'oc_oc1',
    a_ac: 'oc_oc1',
    a_can: 'oc_oc2',
    oc_level: 'oc_oc2',
}).map(([alias, source]) => [alias, {
    configurable: true,
    enumerable: false,
    get() { return this[source]; },
    set(value) { this[source] = value; },
}]));

export function defineObjclassAliases(object) {
    return Object.defineProperties(object, OBJCLASS_ALIAS_DESCRIPTORS);
}

// Copy one live objects[] entry, its aliases included. A bare spread loses
// them: defineObjclassAliases() installs each alias as a non-enumerable
// accessor over the field it shares, so a spread copy answers undefined for
// oc_armcat, a_ac, oc_bimanual and the five others, and a reader of the copy
// takes a different branch from the same data.
export function copyObjclassEntry(entry) {
    return defineObjclassAliases({ ...entry });
}

function cloneObject(template) {
    return defineObjclassAliases({
        ...template,
        oc_uname: null,
        oc_sell_minseen: UNSEEN_OBJECT_PRICE,
        oc_sell_maxseen: 0,
        oc_buy_minseen: UNSEEN_OBJECT_PRICE,
        oc_buy_maxseen: 0,
    });
}

function cloneDescription(template) {
    return { ...template };
}

// C ref: src/objects.c objects_globals_init.
export function objects_globals_init(state = game) {
    state.objects = OBJECT_TEMPLATES.map(cloneObject);
    state.obj_descr = OBJECT_DESCRIPTIONS.map(cloneDescription);
    return state.objects;
}

export function getObjects(state = game) {
    return state.objects;
}

export function getObjectDescriptions(state = game) {
    return state.obj_descr;
}

export function OBJ_NAME(object, state = game) {
    return state.obj_descr[object.oc_name_idx].oc_name;
}

export function OBJ_DESCR(object, state = game) {
    return state.obj_descr[object.oc_descr_idx].oc_descr;
}
